const sum=(a,f)=>a.reduce((s,r)=>s+(f(r)||0),0);
const avg=a=>a.length?sum(a,x=>x)/a.length:null;
const ratio=(a,b)=>b?a/b:null;
function metrics(rows,type,threshold=20){if(type==='calls'){const answered=rows.filter(r=>r.answered),abandoned=rows.filter(r=>r.abandoned),fcr=answered.filter(r=>r.fcr!==null);return {total:rows.length,answered:answered.length,abandoned:abandoned.length,attention:ratio(answered.length,rows.length),aht:avg(answered.filter(r=>r.talk!==null).map(r=>r.talk)),wait:avg(rows.filter(r=>r.wait!==null).map(r=>r.wait)),sla:ratio(answered.filter(r=>r.wait!==null&&r.wait<=threshold).length,rows.length),fcr:ratio(fcr.filter(r=>r.fcr).length,fcr.length),fcrN:fcr.length};}const valid=rows.filter(r=>r.amount!==null),conv=rows.filter(r=>r.conversionValid),transactions=new Set(rows.map(r=>r.transaction)).size,validTransactions=new Set(valid.map(r=>r.transaction)).size;return {total:sum(valid,r=>r.amount),transactions,validTransactions,average:ratio(sum(valid,r=>r.amount),validTransactions),conversion:ratio(sum(conv,r=>r.conversions),sum(conv,r=>r.opportunities)),conversionN:conv.length,invalidMoney:rows.length-valid.length};}
function inService(r){const t=new Date(r.t);const minutes=t.getUTCHours()*60+t.getUTCMinutes()+t.getUTCSeconds()/60;return minutes>=8*60&&minutes<23*60;}
