function card(label,value,detail,icon,cls=''){return `<article class="kpi ${cls}"><div class="kpi-label">${label}<span class="kpi-icon" aria-hidden="true">${icon}</span></div><div class="kpi-value">${value}</div><div class="kpi-detail">${detail}</div></article>`;}
